import java.util.Scanner;

public class Main {
    static final int SIZE = 5;
    static int[] cq = new int[SIZE];
    static int front = -1, rear = -1;

    public static void insert(int val) {
        if ((front == 0 && rear == SIZE - 1) || (rear + 1 == front)) {
            System.out.println("Overflow");
            return;
        }
        if (front == -1) {
            front = rear = 0;
        } else if (rear == SIZE - 1 && front != 0) {
            rear = 0;
        } else {
            rear++;
        }
        cq[rear] = val;
    }

    public static void delete() {
        if (front == -1) {
            System.out.println("Underflow");
            return;
        }
        int val = cq[front];
        if (front == rear) {
            front = rear = -1;
        } else if (front == SIZE - 1) {
            front = 0;
        } else {
            front++;
        }
        System.out.println(val);
    }

    public static void display() {
        if (front == -1) {
            System.out.println("Empty");
            return;
        }
        if (rear >= front) {
            for (int i = front; i <= rear; i++) {
                System.out.print(cq[i] + (i == rear ? "" : " "));
            }
        } else {
            for (int i = front; i < SIZE; i++) {
                System.out.print(cq[i] + " ");
            }
            for (int i = 0; i <= rear; i++) {
                System.out.print(cq[i] + (i == rear ? "" : " "));
            }
        }
        System.out.println();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int ch = sc.nextInt();
            if (ch == 1) insert(sc.nextInt());
            else if (ch == 2) delete();
            else if (ch == 3) display();
            else if (ch == 4) break;
        }
        sc.close();
    }
}

import java.util.Scanner;

public class Main {
    static class Node {
        int data;
        Node next;
        Node(int d) { data = d; next = null; }
    }
    static Node head = null;

    public static void insert(int val) {
        Node n = new Node(val);
        if (head == null) {
            head = n;
            return;
        }
        Node t = head;
        while (t.next != null) t = t.next;
        t.next = n;
    }

    public static void delete(int val) {
        if (head == null) {
            System.out.println("Not Found");
            return;
        }
        if (head.data == val) {
            head = head.next;
            System.out.println("Deleted");
            return;
        }
        Node prev = head;
        while (prev.next != null && prev.next.data != val) {
            prev = prev.next;
        }
        if (prev.next == null) {
            System.out.println("Not Found");
        } else {
            prev.next = prev.next.next;
            System.out.println("Deleted");
        }
    }

    public static void search(int val) {
        Node t = head;
        while (t != null) {
            if (t.data == val) {
                System.out.println("Found");
                return;
            }
            t = t.next;
        }
        System.out.println("Not Found");
    }

    public static void display() {
        if (head == null) {
            System.out.println("Empty");
            return;
        }
        Node t = head;
        while (t != null) {
            System.out.print(t.data + (t.next == null ? "" : " "));
            t = t.next;
        }
        System.out.println();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int ch = sc.nextInt();
            if (ch == 1) insert(sc.nextInt());
            else if (ch == 2) delete(sc.nextInt());
            else if (ch == 3) search(sc.nextInt());
            else if (ch == 4) display();
            else if (ch == 5) break;
        }
        sc.close();
    }
}

